// The Ofir runtime: the C functions generated code calls
// (docs/design/runtime.md). Every name is prefixed `ofir_`.

#ifndef OFIR_RT_H
#define OFIR_RT_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

// The process entry point generated by the compiler from `fn main()`.
void ofir_main(void);

// A source location, emitted by the compiler as a constant global.
typedef struct {
    const char *file;
    uint32_t line, col;
} OfirLoc;

// `str`: an owned, growable byte string. A literal has `cap == 0` and points
// to read-only memory; it is copied to the heap on first modification.
typedef struct {
    uint8_t *ptr;
    int64_t len;
    int64_t cap;
} OfirStr;

// ---------------------------------------------------------------------------
// Panics: print `panic: <message>` and the location, exit with status 101.

#define OFIR_PANIC_STATUS 101

_Noreturn void ofir_panic(const uint8_t *msg, int64_t len, const OfirLoc *loc);
_Noreturn void ofir_panic_overflow(const OfirLoc *loc);
_Noreturn void ofir_panic_div_zero(const OfirLoc *loc);
_Noreturn void ofir_panic_shift(const OfirLoc *loc);
_Noreturn void ofir_panic_cast(const OfirLoc *loc);
_Noreturn void ofir_panic_bounds(int64_t index, int64_t len, const OfirLoc *loc);
_Noreturn void ofir_panic_assert(const OfirLoc *loc);
_Noreturn void ofir_panic_str(const OfirStr *msg, const OfirLoc *loc);   // panic("...")

// Reports a fault near the end of the main stack as `panic: stack
// overflow` (exit status 101); `top` is an address in main's frame.
void ofir_stack_guard_init(void *top);

// ---------------------------------------------------------------------------
// Memory: never returns NULL (panics when out of memory).

void *ofir_alloc(int64_t size);
void *ofir_realloc(void *ptr, int64_t size);
void *ofir_alloc_aligned(int64_t size, int64_t align);      // align > 16
void *ofir_realloc_aligned(void *ptr, int64_t size, int64_t align);
void ofir_free(void *ptr);

// The small-block pool (pool.c): ofir_pool_alloc takes 1 to OFIR_POOL_MAX
// bytes and returns NULL when the pool is off.
#define OFIR_POOL_MAX 512
void *ofir_pool_alloc(int64_t size);
bool ofir_pool_owns(const void *ptr);
int64_t ofir_pool_block_size(const void *ptr);
void ofir_pool_free(void *ptr);
bool ofir_pool_try_free(void *ptr);   // frees a pool block, or returns false
void ofir_pool_thread_exit(void);   // gives a task thread's free blocks back

// ---------------------------------------------------------------------------
// Standard output, buffered by the runtime and flushed at exit and on panic.

void ofir_stdout_write(const uint8_t *ptr, int64_t len);
void ofir_stdout_flush(void);
void ofir_write(int fd, const uint8_t *ptr, int64_t len);

void ofir_print_str(const OfirStr *s);
void ofir_print_int(int64_t value);
void ofir_print_uint(uint64_t value);
void ofir_print_float(double value);
void ofir_print_f32(float value);
void ofir_print_bool(bool value);
void ofir_print_newline(void);

// ---------------------------------------------------------------------------
// Strings: building the value of an interpolation.

// `str` values are passed by pointer, which keeps the C ABI simple.
void ofir_str_push_bytes(OfirStr *s, const uint8_t *ptr, int64_t len);
void ofir_str_push_str(OfirStr *s, const OfirStr *part);
void ofir_str_push_int(OfirStr *s, int64_t value);
void ofir_str_push_uint(OfirStr *s, uint64_t value);
void ofir_str_push_float(OfirStr *s, double value);
void ofir_str_push_f32(OfirStr *s, float value);
void ofir_str_push_bool(OfirStr *s, bool value);
// Format specifiers, `{x:spec}` (spec 1.7).
void ofir_str_push_fixed(OfirStr *s, double value, int64_t digits);
// `format`: the radix (2 or 16), the bits of the type shifted by 8, bit 16 for
// upper case digits; the low bits of `value` are shown.
void ofir_str_push_radix(OfirStr *s, uint64_t value, int64_t format);
// `padding`: the width, bit 32 for left aligned, bit 33 for zero padded.
void ofir_str_push_padded(OfirStr *s, const OfirStr *part, int64_t padding);
// `part` quoted, with escapes: its debug representation (`{x:?}`).
void ofir_str_push_debug(OfirStr *s, const OfirStr *part);
void ofir_str_drop(OfirStr *s);

void ofir_str_concat(OfirStr *out, const OfirStr *a, const OfirStr *b);
bool ofir_str_eq(const OfirStr *a, const OfirStr *b);
int32_t ofir_str_cmp(const OfirStr *a, const OfirStr *b);   // <0, 0 or >0, bytewise

// ---------------------------------------------------------------------------
// The system (std.os, std.fs, std.io): 0 or an errno value. Buffers are
// allocated with ofir_alloc; std takes them over as strings or lists.

typedef struct {
    uint8_t *ptr;
    int64_t len;
} OfirBuf;

typedef struct {
    int64_t status;   // the exit status, or -1 if a signal ended the process
    OfirBuf out, err;
} OfirRun;

void ofir_set_args(int argc, char **argv);
int64_t ofir_arg_count(void);
const uint8_t *ofir_arg(int64_t i, int64_t *len);
const uint8_t *ofir_os_name(int64_t *len);     // "linux", "macos", "windows"
const uint8_t *ofir_arch_name(int64_t *len);   // "x86_64", "aarch64"
const uint8_t *ofir_env(const uint8_t *name, int64_t len, int64_t *value_len);   // NULL: unset
_Noreturn void ofir_exit(int64_t code);
int64_t ofir_test_index(void);   // the test `ofir test` asked for, or -1
int64_t ofir_now_ns(void);       // a monotonic clock, in nanoseconds

// Tasks (task.c, spec 14.2): std.task defines ofir_task_entry.
void *ofir_task_spawn(void *job);   // starts a thread that runs the job
void ofir_task_join(void *thread);  // waits for it and frees the handle
void ofir_tasks_started(void);      // from now on stdout takes a lock

// Channels (channel.c, spec 14.4): queues of values that std.sync boxed.
void *ofir_channel_new(void);                   // one sender, one receiver
bool ofir_channel_send(void *ch, void *value);  // false once the receiver closed
void *ofir_channel_recv(void *ch);              // waits; NULL when no sender is left
void *ofir_channel_try_recv(void *ch);          // NULL when the queue is empty
void ofir_channel_add_sender(void *ch);
void ofir_channel_drop_sender(void *ch);        // the last one wakes the receiver
void ofir_channel_close(void *ch);              // later sends fail
void ofir_channel_drop_receiver(void *ch);      // after close and draining

// Atomics, locks and wait groups (sync.c, spec 14.4). The atomics are
// sequentially consistent.
int64_t ofir_atomic_load(int64_t *p);
void ofir_atomic_store(int64_t *p, int64_t value);
int64_t ofir_atomic_fetch_add(int64_t *p, int64_t delta);   // the old value
int64_t ofir_atomic_swap(int64_t *p, int64_t value);        // the old value
bool ofir_atomic_compare_exchange(int64_t *p, int64_t expected, int64_t desired);
void *ofir_mutex_new(void);
void ofir_mutex_lock(void *m);
void ofir_mutex_unlock(void *m);
void ofir_mutex_free(void *m);
void *ofir_rwlock_new(void);
void ofir_rwlock_read(void *l);
void ofir_rwlock_write(void *l);
void ofir_rwlock_unlock(void *l);
void ofir_rwlock_free(void *l);
void *ofir_waitgroup_new(void);
bool ofir_waitgroup_add(void *wg, int64_t delta);   // false if the count would go below 0
void ofir_waitgroup_wait(void *wg);                 // until the count is 0
void ofir_waitgroup_free(void *wg);
void ofir_stdout_publish(void);     // this thread's pending line to the buffer
// Processes (os.c, ADR 0033): `args` holds `count` NUL-terminated strings,
// the program first. ofir_child_free waits for a child not waited for yet.
int32_t ofir_spawn(const uint8_t *args, int64_t len, int64_t count, void **child);
void ofir_wait(void *child, OfirRun *run);
void ofir_child_free(void *child);
int64_t ofir_cpu_count(void);
uint64_t ofir_random_u64(void);
int32_t ofir_run(const uint8_t *args, int64_t len, int64_t count, OfirRun *run);   // spawn, wait
char *ofir_c_string(const uint8_t *ptr, int64_t len);   // NULL if it holds a NUL

int32_t ofir_read_file(const uint8_t *path, int64_t len, OfirBuf *out);
int32_t ofir_write_file(const uint8_t *path, int64_t len, const uint8_t *data, int64_t n);
bool ofir_path_exists(const uint8_t *path, int64_t len);
int32_t ofir_remove_file(const uint8_t *path, int64_t len);
int32_t ofir_rename(const uint8_t *from, int64_t from_len, const uint8_t *to, int64_t to_len);
int32_t ofir_file_info(const uint8_t *path, int64_t len, int64_t *size, int64_t *modified);
int32_t ofir_touch(const uint8_t *path, int64_t len);
int32_t ofir_canonicalize(const uint8_t *path, int64_t len, OfirBuf *out);
int32_t ofir_create_dir_all(const uint8_t *path, int64_t len);
int32_t ofir_read_dir(const uint8_t *path, int64_t len, OfirBuf *out);
int32_t ofir_read_line(OfirBuf *out);
int32_t ofir_read_stdin(OfirBuf *out);
int32_t ofir_read_bytes(int64_t n, OfirBuf *out);
int32_t ofir_current_dir(OfirBuf *out);
int32_t ofir_executable_path(OfirBuf *out);
int32_t ofir_error_kind(int32_t code);
const uint8_t *ofir_error_message(int32_t code, int64_t *len);

// Formats into `buf` (OFIR_FORMAT_SIZE bytes) and returns the length.
#define OFIR_FORMAT_SIZE 48
int ofir_format_int(char *buf, int64_t value);
int ofir_format_uint(char *buf, uint64_t value);
int ofir_format_float(char *buf, double value);   // shortest round-trip form
int ofir_format_f32(char *buf, float value);      // shortest form that reads back as `value`

#endif
